:root {
  --color-primary: #6b4423;
  --color-primary-dark: #4a2f18;
  --color-accent: #d4a574;
  --color-accent-on-dark: #f5e6d3;
  --color-bg: #faf8f3;
  --color-text: #2c2416;
  --color-text-light: #6b5d52;
  --color-success: #4a7c59;
  --color-border: #e8dcc8;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --spacing-xxl: 4rem;
  --radius: 0.5rem;
  --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.08);
  --shadow-md: 0 4px 16px rgba(0, 0, 0, 0.12);
  --transition: 0.3s ease;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: Georgia, serif;
  font-size: 1rem;
  line-height: 1.6;
  color: var(--color-text);
  background-color: var(--color-bg);
}

a {
  color: var(--color-primary-dark);
  text-decoration: none;
  transition: color var(--transition);
}

a:hover {
  color: var(--color-accent);
}

a:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

header {
  background-color: var(--color-primary);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-md) 0;
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: var(--shadow-sm);
}

header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-family: "Brush Script MT", "Segoe Script", cursive;
  font-size: clamp(1.5rem, 5vw, 2rem);
  font-weight: 400;
  color: var(--color-accent-on-dark);
  text-decoration: none;
  text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);
  letter-spacing: 0.05em;
}

.logo:hover,
.logo:focus {
  color: var(--color-accent-on-dark);
}

.logo:focus {
  outline-offset: 4px;
}

nav[aria-label="Page sections"] {
  display: flex;
  gap: var(--spacing-lg);
}

nav[aria-label="Page sections"] a {
  color: var(--color-accent-on-dark);
  font-size: 0.95rem;
  border-bottom: 2px solid transparent;
  padding-bottom: 0.25rem;
  transition: border-color var(--transition), color var(--transition);
}

nav[aria-label="Page sections"] a:hover {
  border-bottom-color: var(--color-accent);
  color: var(--color-accent);
}

nav[aria-label="Page sections"] a:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 4px;
}

footer {
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-xxl) 0 var(--spacing-lg);
  margin-top: var(--spacing-xxl);
}

footer a {
  color: var(--color-accent);
}

footer a:hover {
  color: var(--color-accent-on-dark);
}

.footer-content {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-lg);
  margin-bottom: var(--spacing-lg);
}

.footer-section h3 {
  margin-bottom: var(--spacing-sm);
  font-size: 1.1rem;
}

.footer-section p {
  margin-bottom: var(--spacing-xs);
  font-size: 0.95rem;
  line-height: 1.5;
}

.copyright {
  text-align: center;
  font-size: 0.85rem;
  color: rgba(245, 230, 211, 0.7);
  border-top: 1px solid rgba(245, 230, 211, 0.2);
  padding-top: var(--spacing-md);
}

h1, h2, h3, h4, h5, h6 {
  font-family: Georgia, serif;
  font-weight: 700;
  line-height: 1.3;
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-sm);
}

h1 {
  font-size: clamp(2rem, 6vw, 3.5rem);
}

h2 {
  font-size: clamp(1.5rem, 5vw, 2.5rem);
}

h3 {
  font-size: 1.25rem;
}

p {
  margin-bottom: var(--spacing-md);
}

button, .btn {
  display: inline-block;
  min-height: 44px;
  padding: var(--spacing-sm) var(--spacing-lg);
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
  border: 2px solid var(--color-primary-dark);
  border-radius: var(--radius);
  font-family: Georgia, serif;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color var(--transition), color var(--transition), border-color var(--transition);
  text-decoration: none;
  text-align: center;
}

button:hover, .btn:hover {
  background-color: var(--color-primary);
  border-color: var(--color-primary);
}

button:focus, .btn:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

button:active, .btn:active {
  transform: scale(0.98);
}

.btn-secondary {
  background-color: transparent;
  color: var(--color-primary-dark);
  border: 2px solid var(--color-accent);
}

.btn-secondary:hover {
  background-color: var(--color-accent);
  color: var(--color-primary-dark);
  border-color: var(--color-accent);
}

form {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: var(--spacing-xs);
  color: var(--color-primary-dark);
}

input[type="text"],
input[type="email"],
input[type="tel"],
input[type="number"],
textarea,
select {
  padding: var(--spacing-sm);
  border: 2px solid var(--color-border);
  border-radius: var(--radius);
  font-family: Georgia, serif;
  font-size: 1rem;
  color: var(--color-text);
  background-color: white;
  transition: border-color var(--transition);
  min-height: 44px;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus,
input[type="number"]:focus,
textarea:focus,
select:focus {
  outline: none;
  border-color: var(--color-primary-dark);
  box-shadow: 0 0 0 3px rgba(107, 68, 35, 0.1);
}

textarea {
  resize: vertical;
  min-height: 120px;
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-lg);
}

.card {
  background-color: white;
  border-radius: var(--radius);
  padding: var(--spacing-lg);
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--transition), transform var(--transition);
}

.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

.card img {
  width: 100%;
  height: auto;
  border-radius: var(--radius);
  margin-bottom: var(--spacing-md);
  display: block;
}

.card h3 {
  margin-bottom: var(--spacing-sm);
}

.card p {
  color: var(--color-text-light);
  margin-bottom: var(--spacing-md);
}

.price {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-md);
}

section {
  padding: var(--spacing-xxl) 0;
}

section:nth-child(even) {
  background-color: white;
}

@media (max-width: 600px) {
  .container {
    padding: 0 var(--spacing-sm);
  }

  header .container {
    flex-direction: column;
    gap: var(--spacing-md);
    align-items: center;
    text-align: center;
  }

  nav[aria-label="Page sections"] {
    flex-direction: column;
    gap: var(--spacing-sm);
    width: 100%;
  }

  nav[aria-label="Page sections"] a {
    display: block;
    padding: var(--spacing-sm);
    border: 1px solid rgba(245, 230, 211, 0.3);
    border-radius: var(--radius);
    border-bottom: none;
  }

  nav[aria-label="Page sections"] a:hover {
    border-bottom: none;
    background-color: rgba(245, 230, 211, 0.2);
  }

  .grid {
    grid-template-columns: 1fr;
  }

  h1 {
    font-size: 1.75rem;
  }

  h2 {
    font-size: 1.35rem;
  }

  section {
    padding: var(--spacing-lg) 0;
  }

  .footer-content {
    grid-template-columns: 1fr;
    text-align: center;
  }

  button, .btn {
    width: 100%;
  }
}

@media (min-width: 601px) {
  nav[aria-label="Page sections"] {
    gap: var(--spacing-lg);
  }

  .grid {
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  }

  section {
    padding: var(--spacing-xxl) 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

pages.css:
.index-hero {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-xxl) 0;
  text-align: center;
}

.index-hero h1 {
  color: var(--color-accent-on-dark);
  margin-bottom: var(--spacing-md);
}

.index-hero-tagline {
  font-size: 1.5rem;
  margin-bottom: var(--spacing-md);
  font-weight: 400;
}

.index-hero-description {
  font-size: 1.1rem;
  max-width: 600px;
  margin: 0 auto var(--spacing-lg);
  color: var(--color-accent-on-dark);
}

.index-hero-buttons {
  display: flex;
  gap: var(--spacing-md);
  justify-content: center;
  flex-wrap: wrap;
}

.index-section-intro {
  text-align: center;
  font-size: 1.1rem;
  color: var(--color-text-light);
  max-width: 600px;
  margin: 0 auto var(--spacing-lg);
}

.index-shop {
  background-color: var(--color-bg);
}

.index-subscription-card {
  position: relative;
  display: flex;
  flex-direction: column;
}

.index-subscription-card h3 {
  margin-bottom: var(--spacing-sm);
}

.index-subscription-frequency {
  font-size: 0.95rem;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-md);
}

.index-subscription-features {
  list-style: none;
  margin-bottom: var(--spacing-lg);
  flex-grow: 1;
}

.index-subscription-features li {
  padding-left: 1.5rem;
  margin-bottom: var(--spacing-sm);
  position: relative;
  color: var(--color-text-light);
}

.index-subscription-features li:before {
  content: "✓";
  position: absolute;
  left: 0;
  color: var(--color-success);
  font-weight: bold;
}

.index-subscription-featured {
  border: 3px solid var(--color-accent);
  transform: scale(1.05);
}

.index-subscription-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background-color: var(--color-accent);
  color: var(--color-primary-dark);
  padding: var(--spacing-xs) var(--spacing-md);
  border-radius: var(--radius);
  font-weight: 700;
  font-size: 0.85rem;
  text-transform: uppercase;
}

.index-subscribe {
  background-color: white;
}

.index-subscribe-details {
  margin-top: var(--spacing-xxl);
  padding-top: var(--spacing-xxl);
  border-top: 2px solid var(--color-border);
}

.index-subscribe-details h3 {
  margin-bottom: var(--spacing-lg);
}

.index-subscribe-steps {
  list-style: none;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-lg);
}

.index-subscribe-steps li {
  padding: var(--spacing-lg);
  background-color: var(--color-bg);
  border-radius: var(--radius);
  border-left: 4px solid var(--color-accent);
}

.index-subscribe-steps strong {
  color: var(--color-primary-dark);
  display: block;
  margin-bottom: var(--spacing-xs);
}

.index-testimonials {
  background-color: var(--color-bg);
}

.index-testimonial-card {
  display: flex;
  flex-direction: column;
}

.index-testimonial-stars {
  color: #d4a574;
  font-size: 1.1rem;
  margin-bottom: var(--spacing-md);
  letter-spacing: 0.2em;
}

.index-testimonial-text {
  font-style: italic;
  color: var(--color-text);
  margin-bottom: var(--spacing-md);
  flex-grow: 1;
  line-height: 1.7;
}

.index-testimonial-author {
  font-weight: 600;
  color: var(--color-primary-dark);
  margin-bottom: 0;
}

.index-cta {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
  color: var(--color-accent-on-dark);
  text-align: center;
  padding: var(--spacing-xxl) 0;
}

.index-cta h2 {
  color: var(--color-accent-on-dark);
  margin-bottom: var(--spacing-md);
}

.index-cta > .container > p {
  font-size: 1.1rem;
  max-width: 600px;
  margin: 0 auto var(--spacing-lg);
  color: var(--color-accent-on-dark);
}

.index-cta-buttons {
  display: flex;
  gap: var(--spacing-md);
  justify-content: center;
  flex-wrap: wrap;
}

@media (max-width: 600px) {
  .index-hero {
    padding: var(--spacing-lg) 0;
  }

  .index-hero-tagline {
    font-size: 1.25rem;
  }

  .index-hero-description {
    font-size: 1rem;
  }

  .index-hero-buttons {
    flex-direction: column;
    gap: var(--spacing-sm);
  }

  .index-hero-buttons .btn {
    width: 100%;
  }

  .index-subscription-featured {
    transform: scale(1);
  }

  .index-subscribe-steps {
    grid-template-columns: 1fr;
  }

  .index-subscribe-steps li {
    padding: var(--spacing-md);
  }

  .index-cta {
    padding: var(--spacing-lg) 0;
  }

  .index-cta-buttons {
    flex-direction: column;
    gap: var(--spacing-sm);
  }

  .index-cta-buttons .btn {
    width: 100%;
  }
}

@media (min-width: 601px) {
  .index-hero-buttons {
    justify-content: center;
    gap: var(--spacing-lg);
  }

  .index-subscription-featured {
    margin-top: -20px;
    margin-bottom: -20px;
  }

  .index-cta-buttons {
    gap: var(--spacing-lg);
  }
}

